네. **파일은 그대로 두고, 메서드 배치만 제안하면** 아래 순서가 더 읽기 좋겠습니다. 앱 시작 흐름을 먼저 읽고, 복잡한 재확인 처리는 뒤에서 읽는 배치입니다.

```ts
// 상태 종류와 시간 설정
NetworkStatus
NetworkCheckStatus
CHECK_NOTICE_DELAY
REFRESH_WAIT_LIMIT

// 저장 상태와 내부 관리 구조
NetworkState
NetworkSession
NetworkRefreshRequest

// 저장소 생성
useNetworkStore

function createNetworkActions(...) {
  // 외부에서 호출하는 동작
  init()
  refresh()
  cleanup()

  // 평소 네트워크 감지 흐름
  subscribe()
  applyObservation()

  // unknown 상태의 확인 안내
  beginUnknownCheck()
  markUnavailable()

  // 재확인 요청의 생성·결과 적용·종료
  startRefreshRequest()
    // 내부: canApplyResult, finish, request

  return { init, cleanup, refresh };
}

// 독립적인 보조 함수
resolveNetworkStatus()
clearNoticeTimer()

// React 밖에서 사용하는 접근 함수
networkStore

// React에서 사용하는 훅
useRealNetworkStatus()
useDisplayNetworkStatus()
useNetworkCheck()
useNetworkControl()
```

지금 배치에서 특히 바꾸면 좋은 곳은 세 군데입니다.

- **`subscribe` 다음에 `applyObservation`**: “감지를 등록하고 → 결과를 받으면 적용한다”는 흐름으로 바로 이어집니다.
- **`beginUnknownCheck` 다음에 `markUnavailable`**: “확인 중으로 시작하고 → 시간이 지나면 확인 불가를 안내한다”는 순서가 됩니다.
- **`startRefreshRequest`는 내부 함수 중 마지막**: 요청 중복·늦은 응답·타이머 처리는 가장 복잡하므로, 기본 감지 흐름을 이해한 뒤 읽게 합니다.

`createNetworkActions()` 안의 함수들은 지금처럼 같은 내부 범위에 두면 됩니다. **새 파일이나 클래스를 만들지 않고, 선언 위치만 정리하는 정도**가 이 코드에는 적절해 보입니다.

function subscribe(session: NetworkSession): boolean {
if (session.unsubscribe) {
return true;
}
```javascript
try {
  // 등록 자체가 첫 상태를 조회하므로 앱의 추가 fetch는 사용하지 않는다.
  session.unsubscribe = NetInfo.addEventListener((state) => {
    if (currentSession !== session) {
      return;
    }

```

여긴 뭐야? unscirbe인데 돼 리스터 등록이고 그런거지?

맞아요. **listener를 등록하는 코드인데, 등록 결과로 받는 “해제 함수”를 `unsubscribe`에 저장해서** 헷갈릴 수 있습니다.

```ts
session.unsubscribe = NetInfo.addEventListener(callback);
```

이 한 줄은 두 가지 일을 합니다.

1. `addEventListener(callback)`으로 네트워크 감지를 등록합니다.
2. 반환된 **감지 해제 함수**를 `session.unsubscribe`에 저장합니다.

등록할 때 해제하는 건 아닙니다. 나중에 cleanup에서 아래처럼 **호출해야** 감지가 해제됩니다.

```ts
session.unsubscribe?.();
```

따라서 앞의 조건은:

```ts
if (session.unsubscribe) {
  return true;
}
```

“해제 함수가 이미 있다면, listener를 이미 등록했다는 뜻이니 중복 등록하지 않는다”는 의미입니다.

callback 안의 조건은:

```ts
if (currentSession !== session) {
  return;
}
```

이 listener가 등록될 때의 `session`과 지금 사용 중인 session을 비교합니다. 이전 감지에서 뒤늦게 들어온 정보라면 무시하는 처리입니다.

import React, {
&#x20; createContext,
&#x20; useCallback,
&#x20; useContext,
&#x20; useEffect,
&#x20; useMemo,
&#x20; useRef,
&#x20; useState,
} from 'react';

import {
&#x20; networkStore,
&#x20; useRealNetworkStatus,
&#x20; type NetworkStatus,
} from '@/shared/store/network';

import { syncData } from './engine';

interface SyncContextValue {
&#x20; isSyncing: boolean;
&#x20; lastSyncedAt: Date | null;
&#x20; triggerManualSync: () => Promise\<void>;
}

interface SyncProviderProps {
&#x20; children: React.ReactNode;
&#x20; enablePeriodicSync?: boolean;
&#x20; syncInterval?: number;
}

type SyncReason =
&#x20; \| 'app-startup'
&#x20; \| 'online-transition'
&#x20; \| 'manual'
&#x20; \| 'periodic';

const DEFAULT\_SYNC\_INTERVAL\_MS = 5 \* 60 \* 1000;

const SyncContext = createContext\<SyncContextValue | null>(null);

export function useSyncContext(): SyncContextValue {
&#x20; const context = useContext(SyncContext);

&#x20; if (!context) {
&#x20;   throw new Error('useSyncContext must be used within SyncProvider');
&#x20; }

&#x20; return context;
}

export function SyncProvider({
&#x20; children,
&#x20; enablePeriodicSync = false,
&#x20; syncInterval = DEFAULT\_SYNC\_INTERVAL\_MS,
}: SyncProviderProps) {
&#x20; const networkStatus = useRealNetworkStatus();

&#x20; const [isSyncing, setIsSyncing] = useState(false);
&#x20; const [lastSyncedAt, setLastSyncedAt] = useState\<Date | null>(null);

&#x20; /\*\*
&#x20;  \* null은 아직 첫 네트워크 상태 effect가 처리되지 않았음을 의미한다.
&#x20;  \* 실제 NetworkStatus의 'unknown'과 초기 미처리 상태를 구분하기 위해 사용한다.
&#x20;  \*/
&#x20; const previousNetworkStatusRef = useRef\<NetworkStatus | null>(null);

&#x20; /\*\*
&#x20;  \* React state는 렌더 사이클 사이에서 즉시 잠금 역할을 보장하지 않으므로,
&#x20;  \* 동시 sync 진입 방지는 ref를 사용한다.
&#x20;  \*/
&#x20; const syncingRef = useRef(false);

&#x20; const executeSync = useCallback(async (reason: SyncReason) => {
&#x20;   if (!canStartSync()) {
&#x20;     logSyncSkipped(reason, 'network-unavailable');
&#x20;     return;
&#x20;   }

&#x20;   if (syncingRef.current) {
&#x20;     logSyncSkipped(reason, 'already-running');
&#x20;     return;
&#x20;   }

&#x20;   syncingRef.current = true;
&#x20;   setIsSyncing(true);

&#x20;   const startedAt = Date.now();

&#x20;   logSyncStarted(reason);

&#x20;   try {
&#x20;     await syncData();

&#x20;     const syncedAt = new Date();

&#x20;     setLastSyncedAt(syncedAt);

&#x20;     logSyncCompleted(reason, {
&#x20;       durationMs: Date.now() - startedAt,
&#x20;       syncedAt,
&#x20;     });
&#x20;   } catch (error) {
&#x20;     logSyncFailed(reason, error, {
&#x20;       durationMs: Date.now() - startedAt,
&#x20;     });
&#x20;   } finally {
&#x20;     syncingRef.current = false;
&#x20;     setIsSyncing(false);
&#x20;   }
&#x20; }, []);

&#x20; const triggerManualSync = useCallback(() => {
&#x20;   return executeSync('manual');
&#x20; }, [executeSync]);

&#x20; useEffect(() => {
&#x20;   const previousStatus = previousNetworkStatusRef.current;

&#x20;   previousNetworkStatusRef.current = networkStatus;

&#x20;   if (
&#x20;     previousStatus === 'online' ||
&#x20;     networkStatus !== 'online'
&#x20;   ) {
&#x20;     return;
&#x20;   }

&#x20;   /\*\*
&#x20;    \* 첫 관측에서 이미 online이면 앱 시작 동기화,
&#x20;    \* 이후 online 복귀는 연결 복구 동기화로 취급한다.
&#x20;    \*/
&#x20;   const reason: SyncReason =
&#x20;     previousStatus === null
&#x20;       ? 'app-startup'
&#x20;       : 'online-transition';

&#x20;   void executeSync(reason);
&#x20; }, [networkStatus, executeSync]);

&#x20; useEffect(() => {
&#x20;   if (!enablePeriodicSync) {
&#x20;     return;
&#x20;   }

&#x20;   logPeriodicSyncEnabled(syncInterval);

&#x20;   const intervalId = setInterval(() => {
&#x20;     void executeSync('periodic');
&#x20;   }, syncInterval);

&#x20;   return () => {
&#x20;     clearInterval(intervalId);
&#x20;   };
&#x20; }, [enablePeriodicSync, syncInterval, executeSync]);

&#x20; const contextValue = useMemo\<SyncContextValue>(
&#x20;   () => ({
&#x20;     isSyncing,
&#x20;     lastSyncedAt,
&#x20;     triggerManualSync,
&#x20;   }),
&#x20;   [isSyncing, lastSyncedAt, triggerManualSync],
&#x20; );

&#x20; return (
&#x20;   \<SyncContext.Provider value={contextValue}>
&#x20;     {children}
&#x20;   \</SyncContext.Provider>
&#x20; );
}

function canStartSync(): boolean {
&#x20; return (
&#x20;   networkStore.realStatus === 'online' &&
&#x20;   networkStore.override === null
&#x20; );
}

type SyncSkipReason =
&#x20; \| 'network-unavailable'
&#x20; \| 'already-running';

function logSyncStarted(reason: SyncReason) {
&#x20; console.info('[Sync] started', {
&#x20;   reason,
&#x20; });
}

function logSyncCompleted(
&#x20; reason: SyncReason,
&#x20; context: {
&#x20;   durationMs: number;
&#x20;   syncedAt: Date;
&#x20; },
) {
&#x20; console.info('[Sync] completed', {
&#x20;   reason,
&#x20;   durationMs: context.durationMs,
&#x20;   syncedAt: context.syncedAt.toISOString(),
&#x20; });
}

function logSyncFailed(
&#x20; reason: SyncReason,
&#x20; error: unknown,
&#x20; context: {
&#x20;   durationMs: number;
&#x20; },
) {
&#x20; console.error('[Sync] failed', {
&#x20;   reason,
&#x20;   durationMs: context.durationMs,
&#x20;   error,
&#x20; });
}

function logSyncSkipped(
&#x20; reason: SyncReason,
&#x20; skipReason: SyncSkipReason,
) {
&#x20; console.debug('[Sync] skipped', {
&#x20;   reason,
&#x20;   skipReason,
&#x20; });
}

function logPeriodicSyncEnabled(syncInterval: number) {
&#x20; console.info('[Sync] periodic sync enabled', {
&#x20;   intervalMs: syncInterval,
&#x20; });
}

