&#x20;   reason,
&#x20;   durationMs,
&#x20;   syncedAt: syncedAt.toISOString(),
&#x20; });
}

function logSyncFailed(
&#x20; reason: SyncReason,
&#x20; error: unknown,
&#x20; durationMs: number,
) {
&#x20; console.error('[Sync] failed', {
&#x20;   reason,
&#x20;   durationMs,
&#x20;   error,
&#x20; });
}

function logSyncSkipped(
&#x20; reason: SyncReason,
&#x20; skipReason: SyncSkipReason,
) {
&#x20; console.debug('[Sync] skipped', {
&#x20;   reason,
&#x20;   skipReason,
&#x20; });
}

function logPeriodicSyncEnabled(intervalMs: number) {
